mapper.select:
SELECT DISTINCT u.first_bbk_id AS bbk_id, u.first_bbk_nm AS bbk_name,
  u.org_id, u.org_nm AS org_name, u.pst_lvl AS level, u.user_name, t.sap_id, p.id AS plan_id, p.created_at
FROM rm_jkh_user_info u
JOIN swe_wealth_plan_targets t ON t.sap_id COLLATE utf8mb4_bin = u.user_id AND t.deleted = 0
JOIN swe_wealth_plans p ON p.id = t.plan_id AND p.deleted = 0

  AND u.first_bbk_id = #{query.bbkId}
  AND u.org_id = #{query.orgId}
  AND u.pst_lvl = #{query.level}

SELECT first_bbk_id AS bbk_id, first_bbk_nm AS bbk_name, org_id, org_nm AS org_name
FROM rm_jkh_user_info WHERE first_bbk_id = #{bbkId} AND org_id = #{orgId}
ORDER BY user_id LIMIT 1

SELECT job_id, trace_id, actual_time, is_read AS `read` FROM swe_cron_executions
WHERE trace_id IN
#{trace}
